const staticData = $getWorkflowStaticData('global');
if (!staticData.seenLinks) staticData.seenLinks = [];

const seen = new Set(staticData.seenLinks);
const newItems = [];

for (const item of $input.all()) {
  const link = item.json.link || item.json.guid;
  if (link && !seen.has(link)) {
    newItems.push(item);
    seen.add(link);
  }
}

staticData.seenLinks = Array.from(seen).slice(-200);

return newItems;

const now = Date.now();
const sevenDaysMs = 7 * 24 * 60 * 60 * 1000;
const candidates = [];

for (const item of $input.all()) {
  const pubDateRaw = item.json.isoDate || item.json.pubDate;
  const pubDate = pubDateRaw ? new Date(pubDateRaw) : null;
  if (pubDate && !isNaN(pubDate.getTime()) && (now - pubDate.getTime()) <= sevenDaysMs) {
    candidates.push({
      title: item.json.title,
      summary: (item.json.contentSnippet || item.json.content || '').slice(0, 300),
      link: item.json.link || item.json.guid,
      pubDate: pubDate.toISOString(),
      _full: item.json
    });
  }
}

if (candidates.length === 0) return [];

const summaryText = candidates.map((c, i) => '[' + i + '] (' + c.pubDate + ') ' + c.title + '\n' + c.summary).join('\n\n');

return [{ json: { candidatesSummary: summaryText, candidatesCount: candidates.length, candidatesRaw: candidates } }];

const raw = $json.candidates[0].content.parts[0].text.trim();
const cleaned = raw.replace(/^```json\s*/i, '').replace(/^```\s*/, '').replace(/```\s*$/, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { selectedIndex: 0, reasoning: 'Fallback: gagal parse hasil seleksi, pakai kandidat pertama.' };
}

const candidatesRaw = $('Build Candidates Summary (Last 7 Days)').item.json.candidatesRaw;
const idx = (parsed.selectedIndex >= 0 && parsed.selectedIndex < candidatesRaw.length) ? parsed.selectedIndex : 0;
const chosen = { ...candidatesRaw[idx]._full };
chosen._selectionReasoning = parsed.reasoning;

return [{ json: chosen }];

const brief = $json.candidates[0].content.parts[0].text.trim();
const imageUrl = 'https://image.pollinations.ai/prompt/' + encodeURIComponent(brief) + '?width=1024&height=1024&nologo=true';
return [{ json: { imageUrl, imageBrief: brief } }];

